//컬럼 컬러 구분을 위한 변수
scwin.check1, scwin.check2, scwin.check3, scwin.check4, scwin.check5, scwin.check6, scwin.check7, scwin.check8, scwin.check9, scwin.check10, scwin.check11, scwin.check12, scwin.check13, scwin.check14, scwin.check15, scwin.check16, scwin.check17;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    //gUpDepCd = js_up_dep_cd;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();

    // 업종 셋팅
    dts_IndTp.DataID = "/CodeAction.do?method=listStdIndtpCB" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R";
    dts_IndTp.Reset();

    // 기업집단 셋팅
    dts_com_grp.DataID = "/CodeAction.do?method=listComGrp" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R";
    dts_com_grp.Reset();
};
scwin.fn_Init = function() {
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    var str = "";
    for (var i = yyyy; i >= 1998; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    //alert(str);
    cmb_FISCYY.CBData = str;
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    if (js_market == "9") {
        rdo_MKT_ID.setDisabled(false);
        $c.stf.setObjectValue(rdo_MKT_ID, "1");
    } else {
        // 콘트롤 잠그기.
        $c.cm.setColumnProp(grd_XBRL2, "MKT_NM", "Show", false);
        rdo_MKT_ID.setDisabled(true);
    }
};



// 법인명이 있고 특정 다른 조건을 선택할때 메세지
scwin.fn_CheckComNmCond = function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isur_cd);
    if (vIsurCd != '') {
        $c.win.alert("해당항목 선택시 법인코드(명)의 조건값이  초기화 됩니다.");
        $c.stf.setObjectValue(txb_isur_cd, '');
        $c.stf.setObjectValue(txb_COM_NM, '');
        return;
    }
};
scwin.fn_listNewsflashFinance = function() {
    scwin.colorCnt = 1; //조회를 클릭한 경우에만 컬럼 color 변경해줌

    var flag = $c.stf.getObjectValue(rdo_MKT_ID);
    var vFISCYY = $c.stf.getObjectValue(cmb_FISCYY);
    var vISUR_CD = $c.stf.getObjectValue(txb_isur_cd);
    if (flag == "9" || flag == "") {
        $c.win.alert("[시장구분]을 선택하세요.");
        rdo_MKT_ID.focus();
        return;
    } else {
        scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
        scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);


        //alert("gDepCd: " + gDepCd);
        //alert("gEmpNo: " + gEmpNo);
        // alert("js_dep_cd: " + js_dep_cd);

        /*
        if (gDepCd == "UPTEAM" ) { //&&  js_dep_cd.substr(2,4) == '00') {		
        	gUpDepCd = js_dep_cd;
        	// gDepCd = '%';
        }
        */

        if (scwin.gEmpNo == "") {
            scwin.gEmpNo = '%';
        }
        if (scwin.gDepCd == "") {
            scwin.gDepCd = 'all';
        }

        //		var url = "/DisclosureStatistics.do?method=listNewsflashFinance";
        //			url += "&MKT_ID=" + getObjectValue(rdo_MKT_ID);
        //			url += "&FISCYY=" + vFISCYY;
        //			url += "&RPT_KIND=" + getObjectValue(cmb_RPT_KIND);
        //		dts_TOBE.DataID = encodeURI(url);
        //		dts_TOBE.Reset();


        scwin.fn_changeHeader();
        $c.cm.ShowWin(grd_XBRL2);
        var url = "/DisclosureStatistics.do?method=listNewsflashXBRL";
        url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID);
        url += "&FISCYY=" + vFISCYY;
        url += "&MM=" + $c.stf.getObjectValue(cmb_MM);
        url += "&RPT_KIND=" + $c.stf.getObjectValue(cmb_RPT_KIND);
        url += "&ISUR_CD=" + vISUR_CD;
        url += "&DEP_CD=" + scwin.gDepCd;
        url += "&EMP_NO=" + scwin.gEmpNo;
        url += "&UP_DEP_CD=" + js_belngdepcd;
        url += "&IND_TP=" + $c.stf.getObjectValue(cmb_IndTp);
        url += "&COM_GRP=" + $c.stf.getObjectValue(cmb_com_grp);
        url += "&MON_UNIT=" + $c.stf.getObjectValue(cmb_mon_unit);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_XBRL.DataID = encodeURI(url);
        var str = dts_XBRL.getCellData(1, 5);
        //dts_XBRL.Text;
        //.ColumnValue(1,2);
        dts_XBRL.Reset();
    }
};



// 공시팀 전체 목록에 추가
scwin.fn_addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM'); //
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    for (var i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE")); //
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE")); //
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};
