scwin.fn_allDisCheck = function() {
    //alert(eval('checkbox_'+num));

    for (var i = 0; i < 21; i++) {
        if (i == 0 || i == 1 || i == 2 || i == 7 || i == 8 || i == 12 || i == 15 || i == 20) {
            continue;
        }
        eval('checkbox_' + i).setValue(0);
    }
};
scwin.fn_allCheck = function() {
    for (var i = 0; i < 21; i++) {
        if (i == 0 || i == 1 || i == 2 || i == 7 || i == 8 || i == 12 || i == 15 || i == 20) {
            continue;
        }
        eval('checkbox_' + i).setValue(1);
    }
};
scwin.fn_showGridField = function(flag) {
    var id = "";
    if (flag == 'SHOW') {
        //grd_XBRL2.ColumnProp('1','Show') = true;
        //grd_XBRL2.ColumnProp('2','Show') = true;
        for (var i = 0; i < 21; i++) {
            id = i;
            if (i == 0 || i == 1 || i == 2 || i == 7 || i == 8 || i == 12 || i == 15 || i == 20) {
                continue;
            }
            $c.cm.setColumnProp(grd_XBRL2, i, 'Show', true);
        }
    } else {
        //grd_XBRL2.ColumnProp('1','Show') = false;
        //grd_XBRL2.ColumnProp('2','Show') = false;
        for (var i = 0; i < 21; i++) {
            id = i;
            if (i == 0 || i == 1 || i == 2 || i == 7 || i == 8 || i == 12 || i == 15 || i == 20) {
                continue;
            }
            $c.cm.setColumnProp(grd_XBRL2, i, 'Show', false);
        }
    }
};
scwin.fn_checkBox = function(i) {
    if (eval('checkbox_' + i).checked) {
