};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "" || scwin.gDepCd == "UPTEAM") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "UPTEAM" ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34') {
        $c.stf.CopyDataSet(dts_dep, dts_dep1);
        scwin.fn_addDsclTeamAll(rowcount);
        $c.stf.setObjectValue(cmb_TeamList, 'UPTEAM');
    }
};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '' || scwin.gDepCd == 'UPTEAM') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 
    if (scwin.gDepCd != '' && scwin.gDepCd != 'UPTEAM') {
        cmb_EmpList.trigger("onclick");
    }
};
scwin.grd_XBRL2_OnUserColor = function(row, colid) {
    //var colorName = "#CBFF75";
    var colorName = "#77FF88"; //11FF00";

    // 2009.03.27 happyhan 추가
    if (dts_XBRL.getCellData(row, "ACPT_NO") == null || dts_XBRL.getCellData(row, "ACPT_NO") == undefined) {
        colorName = "#ffffff"; // 데이타가 없으면 흰색으로

    }

    // 2009.03.27 happyhan 추가 : 회사정보결산월과 xbrl 재무정보의 결산월 비교
    if (colid == "acolor0") {
        var mm1 = dts_XBRL.getCellData(row, "ACNTCLS_MM");
        var mm2 = dts_XBRL.getCellData(row, "ACNTCLS_MMDD1");
        if (scwin.colorCnt > 0 && mm1 != mm2) {
            return colorName; // 연두색
        } else {
            //	return decode(row-tointeger(row/2)*2,0,'#f2f5f9',1,'#ffffff');
            /*
            if ( row - Math.int( row/2) *2 == 0 ) return "#f2f5f9"
            else return "#ffffff";
            */
            return "#ffffff";
        }
    }
    if (colid == "acolor1") {
        scwin.check1 = dts_XBRL.getCellData(row, "AUDT_OPIN_TP_NM");
        if (scwin.colorCnt > 0 && scwin.check1 != "적정" && scwin.check1 != "의견거절" && scwin.check1 != "한정" && scwin.check1 != "부적정") {
            return colorName; // 연두색
        } else {
            //	return decode(row-tointeger(row/2)*2,0,'#f2f5f9',1,'#ffffff');
            /*
            if ( row - Math.int( row/2) *2 == 0 ) return "#f2f5f9"
            else return "#ffffff";
